    export type UpdateStudyTopicMutationBody = BodyType<StudyTopicUpdate>
    export type UpdateStudyTopicMutationError = ErrorType<unknown>
    export type UpdateStudyTopicMutationVariables = {topicId: number;data: BodyType<StudyTopicUpdate>}

